import re


_PARTS = re.compile(r" *([0-9]+[dhms](?: *[0-9]+[dhms])*) *\Z")
_UNIT_VALUES = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {"d": 0, "h": 1, "m": 2, "s": 3}


def parse(text):
    """Parse a duration string into whole seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    match = _PARTS.fullmatch(text)
    if match is None:
        raise ValueError("invalid duration")

    total = 0
    previous = -1
    for amount, unit in re.findall(r"([0-9]+)([dhms])", match.group(1)):
        order = _UNIT_ORDER[unit]
        if order <= previous:
            raise ValueError("duration units must be unique and ordered")
        previous = order
        total += int(amount) * _UNIT_VALUES[unit]
    return total


def format(seconds):
    """Format a non-negative integer number of seconds compactly."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    parts = []
    for unit, value in (("d", 86400), ("h", 3600), ("m", 60), ("s", 1)):
        amount, seconds = divmod(seconds, value)
        if amount:
            parts.append(f"{amount}{unit}")
    return "".join(parts)

import unittest

from durations import format, parse


class ParseTests(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(parse("1h30m"), 5400)
        self.assertEqual(parse("90s"), 90)
        self.assertEqual(parse("2d 4h"), 187200)
        self.assertEqual(parse("1d2h3m4s"), 93784)

    def test_larger_component_values_and_spaces(self):
        self.assertEqual(parse("90m"), 5400)
        self.assertEqual(parse("  1d  2h  "), 93600)

    def test_zero_components(self):
        self.assertEqual(parse("0d0h0m0s"), 0)

    def test_invalid_strings(self):
        for text in (
            "", "   ", "-1s", "1.5h", "10", "1w", "1h1h", "1m1h",
            "1s2m", "1 h", "1h 2", "1h\t2m", "1h\n",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse(text)

    def test_non_string(self):
        with self.assertRaises(ValueError):
            parse(3)


class FormatTests(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(format(3661), "1h1m1s")
        self.assertEqual(format(86400), "1d")
        self.assertEqual(format(0), "0s")

    def test_no_zero_units_and_large_values(self):
        self.assertEqual(format(86400 + 1), "1d1s")
        self.assertEqual(format(90061), "1d1h1m1s")

    def test_rejects_invalid_values(self):
        for value in (-1, 1.0, "1", None, True, False):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    format(value)


