import re


_UNITS = (("d", 86400), ("h", 3600), ("m", 60), ("s", 1))
_PARSE_RE = re.compile(r"([0-9]+)([dhms])")


def parse(text):
    """Parse a duration string into whole seconds."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    total = 0
    last_rank = -1
    pos = 0
    while pos < len(text):
        # Whitespace is permitted only between duration components.
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break

        match = _PARSE_RE.match(text, pos)
        if match is None:
            raise ValueError("invalid duration")

        amount = int(match.group(1))
        unit = match.group(2)
        rank = "dhms".index(unit)
        if rank <= last_rank:
            raise ValueError("duration units must be unique and ordered")
        last_rank = rank
        total += amount * dict(_UNITS)[unit]
        pos = match.end()

        if pos < len(text) and not text[pos].isspace() and not text[pos].isdigit():
            raise ValueError("invalid duration")

    return total


def format(seconds):
    """Format a non-negative integer number of seconds compactly."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    parts = []
    for unit, size in _UNITS:
        amount, seconds = divmod(seconds, size)
        if amount:
            parts.append(f"{amount}{unit}")
    return "".join(parts)

