"""Parse and format compact duration strings."""

_UNITS = (("d", 86400), ("h", 3600), ("m", 60), ("s", 1))


def parse(text):
    """Return the whole-second length of a duration string.

    Components must be non-negative whole numbers followed by d, h, m, or s,
    in descending unit order. Components may be separated by ASCII spaces.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip(" ")
    if not text:
        raise ValueError("duration cannot be empty")

    unit_values = dict(_UNITS)
    total = 0
    previous_rank = -1
    i = 0
    length = len(text)

    while i < length:
        start = i
        while i < length and "0" <= text[i] <= "9":
            i += 1
        if start == i or i == length:
            raise ValueError("expected a number followed by a unit")

        # Accumulate manually so very large numbers aren't subject to the
        # interpreter's limit on decimal-string-to-int conversions.
        value = 0
        for digit in text[start:i]:
            value = value * 10 + ord(digit) - ord("0")

        unit = text[i]
        if unit not in unit_values:
            raise ValueError("unknown or missing unit")
        rank = next(rank for rank, (name, _) in enumerate(_UNITS) if name == unit)
        if rank <= previous_rank:
            raise ValueError("units must appear once, in descending order")
        total += value * unit_values[unit]
        previous_rank = rank
        i += 1

        if i < length:
            if text[i] != " ":
                raise ValueError("components must be separated by spaces")
            while i < length and text[i] == " ":
                i += 1
            if i == length:
                raise ValueError("trailing spaces are only allowed at the end")

    return total


def format(seconds):
    """Return a non-negative integer number of seconds in shortest form."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if seconds == 0:
        return "0s"

    parts = []
    remaining = seconds
    for unit, size in _UNITS:
        amount, remaining = divmod(remaining, size)
        if amount:
            parts.append(f"{amount}{unit}")
    return "".join(parts)

