"""Parse and format compact duration strings."""

_UNITS = (("d", 86400), ("h", 3600), ("m", 60), ("s", 1))


def parse(text):
    """Return the number of seconds represented by a duration string.

    Parts must use each of d, h, m, s at most once and in that order.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    unit_values = dict(_UNITS)
    unit_order = {unit: index for index, (unit, _) in enumerate(_UNITS)}
    total = 0
    last_index = -1
    position = 0
    length = len(text)

    while position < length:
        # Spaces are permitted only between complete parts.
        start = position
        while position < length and "0" <= text[position] <= "9":
            position += 1
        if position == start or position >= length:
            raise ValueError("expected an integer and a unit")

        # Accumulate manually so the accepted number length is not limited by
        # Python's configurable decimal-string conversion limit.
        value = 0
        for digit in text[start:position]:
            value = value * 10 + (ord(digit) - ord("0"))

        unit = text[position]
        if unit not in unit_values:
            raise ValueError("unknown duration unit")
        index = unit_order[unit]
        if index <= last_index:
            raise ValueError("units must appear once in descending order")
        last_index = index
        total += value * unit_values[unit]
        position += 1

        if position < length:
            if text[position] == " ":
                while position < length and text[position] == " ":
                    position += 1
                if position == length:
                    # Normally removed by strip(), retained for clarity.
                    raise ValueError("unexpected trailing space")
            # Otherwise the next character must begin the next number.
            if position < length and not ("0" <= text[position] <= "9"):
                raise ValueError("invalid character between parts")

    return total


def format(seconds):
    """Return a non-negative integer number of seconds in canonical form."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative integer")
    if seconds == 0:
        return "0s"

    parts = []
    remaining = seconds
    for unit, value in _UNITS:
        amount, remaining = divmod(remaining, value)
        if amount:
            parts.append(f"{amount}{unit}")
    return "".join(parts)

