"""Parse and format compact duration strings."""

import re


_PART = re.compile(r"([0-9]+)([dhms])")
_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate("dhms")}


def parse(text):
    """Return the whole-second length of a duration string.

    Components must use d, h, m, s in that order, without repeating a unit.
    Components may touch or be separated by spaces.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    value = text.strip(" ")
    if not value:
        raise ValueError("duration cannot be empty")

    total = 0
    position = 0
    previous_order = -1
    while position < len(value):
        # Spaces are allowed only between complete components.
        while position < len(value) and value[position] == " ":
            position += 1
        match = _PART.match(value, position)
        if match is None:
            raise ValueError("invalid duration component")

        amount = int(match.group(1))
        unit = match.group(2)
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("duration units are repeated or out of order")
        total += amount * _UNIT_SECONDS[unit]
        previous_order = order
        position = match.end()

        if position < len(value) and value[position] != " ":
            raise ValueError("invalid character between duration components")

    return total


def format(seconds):
    """Return a non-negative integer number of seconds in shortest form."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    parts = []
    for unit, unit_seconds in _UNIT_SECONDS.items():
        count, seconds = divmod(seconds, unit_seconds)
        if count:
            parts.append(f"{count}{unit}")
    return "".join(parts)

