import re


_PARTS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_UNIT_ORDER = {unit: index for index, unit in enumerate("dhms")}
_DURATION_RE = re.compile(r"[0-9]+[dhms](?: *[0-9]+[dhms])*")


def parse(text):
    """Return the whole-second length of a duration string.

    Parts must use d, h, m, s units in strictly decreasing order, with
    optional ASCII spaces between parts.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    value = text.strip(" ")
    if not value or _DURATION_RE.fullmatch(value) is None:
        raise ValueError("invalid duration")

    total = 0
    previous_order = -1
    for number, unit in re.findall(r"([0-9]+)([dhms])", value):
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("duration units must appear once in descending order")
        previous_order = order
        total += int(number) * _PARTS[unit]
    return total


def format(seconds):
    """Return a non-negative integer number of seconds in shortest form."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    result = []
    remainder = seconds
