    value = 0
    for char in digits:
        value = value * 10 + ord(char) - ord("0")
    return value


def _int_to_decimal(value):
    """Convert a non-negative integer without relying on Python's string digit limit."""
    if value == 0:
        return "0"
    base = 10**1000
    chunks = []
    while value:
        value, remainder = divmod(value, base)
        chunks.append(remainder)
    return str(chunks[-1]) + "".join(f"{chunk:01000d}" for chunk in reversed(chunks[:-1]))


def parse(text):
    """Return the number of seconds represented by a duration string.

    Parts consist of a non-negative whole number and one unit (d, h, m, s),
    in descending unit order. Spaces may separate parts.
    """
    if not isinstance(text, str) or not text:
        raise ValueError("duration must be a non-empty string")

    position = 0
    total = 0
    previous_unit_index = -1
    length = len(text)

    while position < length and text[position] == " ":
        position += 1

    if position == length:
        raise ValueError("duration must contain at least one part")

    while position < length:
        start = position
        while position < length and "0" <= text[position] <= "9":
            position += 1
        if position == start or position >= length:
            raise ValueError("each duration part needs a number and unit")

        amount = _decimal_to_int(text[start:position])
        unit = text[position]
        unit_index = next((i for i, (name, _) in enumerate(_UNITS) if name == unit), None)
        if unit_index is None or unit_index <= previous_unit_index:
            raise ValueError("units must appear once in descending order")
        total += amount * _UNITS[unit_index][1]
        previous_unit_index = unit_index
        position += 1

        if position == length:
            break
        if text[position] == " ":
            while position < length and text[position] == " ":
                position += 1
            if position == length:
                break
            continue
        # The next part can immediately follow this one, but must begin with a digit.
        if not ("0" <= text[position] <= "9"):
            raise ValueError("invalid character between duration parts")

    return total


