    """Return the shortest d/h/m/s representation of a non-negative integer."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")
    if seconds == 0:
        return "0s"

    parts = []
    remainder = seconds
    for unit, size in _UNITS:
        amount, remainder = divmod(remainder, size)
        if amount:
            parts.append(_int_to_decimal(amount) + unit)
    return "".join(parts)

