"""Parse and format compact duration strings."""


def parse(text):
    """Return the number of seconds represented by a duration string.

    Durations consist of ordered, non-repeating d/h/m/s components, with
    optional ASCII spaces between components.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip(" ")
    if not text:
        raise ValueError("duration cannot be empty")

    unit_seconds = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    unit_order = {"d": 0, "h": 1, "m": 2, "s": 3}
    total = 0
    previous = -1
    index = 0
    length = len(text)

    while index < length:
        start = index
        value = 0
        while index < length and "0" <= text[index] <= "9":
            value = value * 10 + (ord(text[index]) - ord("0"))
            index += 1
        if index == start or index >= length:
            raise ValueError("invalid duration component")

        unit = text[index]
        if unit not in unit_seconds:
            raise ValueError("unknown duration unit")
        order = unit_order[unit]
        if order <= previous:
            raise ValueError("duration units must be in descending order")
        previous = order
        total += value * unit_seconds[unit]
        index += 1

        if index < length and text[index] == " ":
            while index < length and text[index] == " ":
                index += 1
            if index == length:
                raise ValueError("invalid trailing separator")

    return total


def format(seconds):
    """Return the shortest d/h/m/s representation of a non-negative int."""
    if type(seconds) is not int or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    parts = []
    for unit, size in (("d", 86400), ("h", 3600), ("m", 60), ("s", 1)):
        amount, seconds = divmod(seconds, size)
        if amount:
            parts.append(f"{amount}{unit}")
    return "".join(parts)

