import re


_PARTS = (("d", 86400), ("h", 3600), ("m", 60), ("s", 1))
_PARSE_RE = re.compile(r"(?:[0-9]+d)?(?:[0-9]+h)?(?:[0-9]+m)?(?:[0-9]+s)?\Z")


def _decimal_to_int(digits):
    """Convert digits without relying on Python's decimal-string length limit."""
    value = 0
    for digit in digits:
        value = value * 10 + (ord(digit) - ord("0"))
    return value


def parse(text):
    """Return the whole-second length of a duration string.

    Components must be ordered d, h, m, s and may be separated by spaces.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    value = text.strip()
    if not value:
        raise ValueError("duration cannot be empty")

    # Spaces are permitted only between complete components.
    compact = value.replace(" ", "")
    if not _PARSE_RE.fullmatch(compact):
        raise ValueError("invalid duration")

    total = 0
    position = 0
    for unit, multiplier in _PARTS:
        match = re.match(r"([0-9]+)" + unit, compact[position:])
        if match:
            total += _decimal_to_int(match.group(1)) * multiplier
            position += match.end()
    if position != len(compact):
        raise ValueError("invalid duration")
    return total


def format(seconds):
    """Return a non-negative integer number of seconds in shortest form."""
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds < 0:
        raise ValueError("seconds must be a non-negative int")

    if seconds == 0:
        return "0s"

    result = []
    remainder = seconds
    for unit, multiplier in _PARTS:
        amount, remainder = divmod(remainder, multiplier)
        if amount:
            result.append(f"{amount}{unit}")
    return "".join(result)

