        cases = [
            "", "   ", "-1s", "+1s", "1.5h", "1", "1x",
            "1h1h", "1m1h", "1s1m", "1h 1 h", "1h\t2m",
            "1h\n2m", "h", "1h ", "1 h", "1hh", "--1s",
        ]
        for text in cases:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse(text)

    def test_non_string(self):
        for value in (None, 1, b"1s"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse(value)


class FormatTests(unittest.TestCase):
    def test_valid_formatting(self):
        cases = {
            0: "0s",
            1: "1s",
            59: "59s",
            60: "1m",
            3661: "1h1m1s",
            86400: "1d",
            90061: "1d1h1m1s",
            187200: "2d4h",
        }
        for seconds, expected in cases.items():
            with self.subTest(seconds=seconds):
                self.assertEqual(format(seconds), expected)

    def test_invalid_values(self):
        for value in (-1, 1.0, "60", None, True, False):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    format(value)


